<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Accounts</h1></div><div class="row"><div class="col-lg-4"><?php if(can('accounts.create')):?><div class="card"><div class="card-header"><h5 class="card-title mb-0">Add Account</h5></div><div class="card-body"><form method="post" action="<?=url('accounts')?>"><?=csrf_field()?><input class="form-control mb-2" name="name" placeholder="Account name" required><select class="form-select mb-2" name="type"><option>Cash</option><option>Bank Account</option><option>Credit Card</option><option>Debit Card</option><option>UPI</option><option>Wallet</option></select><input class="form-control mb-2" name="opening_balance" type="number" step="0.01" value="0"><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><select class="form-select mb-3" name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select><button class="btn btn-primary">Create</button></form></div></div><?php endif;?></div><div class="col-lg-8"><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td class="fw-semibold"><?=money($r['balance'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>